// 1. Basis-Objekt für den Home Assistant Service erstellen
let serviceData = {
    title: msg.benachrichtigung.title,
    message: msg.benachrichtigung.message || "Leere Nachricht", 
    data: {} 
};

// 2. Prüfen, ob das data-Objekt existiert und Werte holen
if (msg.benachrichtigung.data) {
    let inData = msg.benachrichtigung.data; 

    function addIfValid(key, value) {
        if (value !== undefined && value !== null && value !== "") {
            serviceData.data[key] = value;
        }
    }

    // 3. Werte prüfen und in serviceData.data schreiben
    addIfValid("ttl", inData.ttl);
    addIfValid("priority", inData.priority);
    addIfValid("channel", inData.channel);
    addIfValid("tts_text", inData.tts);
    addIfValid("chronometer", inData.chronometer);
    addIfValid("when", inData.when);
    addIfValid("when_relative", inData.when_relative);
    addIfValid("live_update", inData.live_update); 
    addIfValid("critical_text", inData.critical_text);
    addIfValid("progress", inData.progress);
    addIfValid("progress_max", inData.progress_max);
    addIfValid("tag", inData.tag);
    addIfValid("notification_icon", inData.notification_icon);
}

// Optional: Leeres data-Objekt löschen, falls keine Extra-Parameter da waren
if (Object.keys(serviceData.data).length === 0) {
    delete serviceData.data;
}

// 4. Alles in msg.payload.data packen
msg.payload = {
    data: serviceData
};

return msg;

