// 1. Schritte aus dem Flow-Kontext laden
// Wenn 'flow.brightnesses' noch nicht existiert, nutzen wir Standardwerte als Fallback
var steps = flow.get('$parent.brightnesses') || [1, 20, 40, 60, 80, 100];

// Zur Sicherheit sortieren wir das Array aufsteigend (1 -> 100)
steps.sort(function (a, b) { return a - b; });

// 2. Aktuellen Wert holen und in Prozent (0-100) umrechnen
// Basierend auf deinem alten Code kommt der Wert als 0-255 rein
var currentByte = msg.lightlevel.attributes.brightness || 1;
var currentPercent = Math.round((currentByte / 255) * 100);

var direction = msg.direction || "up"; // Standard-Richtung

// 3. Den aktuellen Index in der Liste finden
// Wir suchen den Schritt, der dem aktuellen Helligkeitswert am nächsten ist.
// Das ist wichtig, falls die Lampe manuell auf einen "krummen" Wert gestellt wurde.
var currentIndex = 0;
var minDiff = 1000;

for (var i = 0; i < steps.length; i++) {
    var diff = Math.abs(steps[i] - currentPercent);
    if (diff < minDiff) {
        minDiff = diff;
        currentIndex = i;
    }
}

// 4. Nächsten Schritt berechnen
var nextIndex = currentIndex;

if (direction == "up") {
    nextIndex++;
    // Wenn wir das Ende der Liste erreichen oder überschreiten
    if (nextIndex >= steps.length - 1) {
        nextIndex = steps.length - 1; // Auf dem höchsten Wert bleiben
        direction = "down";           // Richtung umkehren für nächstes Mal
    }
} else { // direction is "down"
    nextIndex--;
    // Wenn wir den Anfang der Liste erreichen oder unterschreiten
    if (nextIndex <= 0) {
        nextIndex = 0;      // Auf dem niedrigsten Wert bleiben
        direction = "up";   // Richtung umkehren für nächstes Mal
    }
}

// 5. Ergebnis setzen
msg.lightlevel = steps[nextIndex];
msg.direction = direction;

return msg;

