// --- 1. Definition der Szenen ---

// Hole die Farblisten aus dem Flow-Kontext.
// Wir verwenden flow.get(), da dies der Standardweg in Node-RED ist.
// Ein Fallback auf "|| []" (ein leeres Array) wird hinzugefügt,
// um Fehler zu vermeiden, falls die Variablen im Flow noch nicht gesetzt sein sollten.
const colors = flow.get('$parent.colors') || [];
const whiteTones = flow.get('$parent.whiteTones') || [];

// --- Hilfsfunktion zur Berechnung der "Distanz" zwischen zwei RGB-Farben ---
function getColorDistance(rgb1, rgb2) {
    if (!rgb1 || !rgb2) return Infinity;
    let r_dist = Math.pow(rgb1[0] - rgb2[0], 2);
    let g_dist = Math.pow(rgb1[1] - rgb2[1], 2);
    let b_dist = Math.pow(rgb1[2] - rgb2[2], 2);
    return Math.sqrt(r_dist + g_dist + b_dist);
}

// --- 2. Aktuellen Status abrufen ---
const attributes = msg.state.attributes || {};
const currentKelvin = attributes.color_temp_kelvin;
const currentRGB = attributes.rgb_color;

// Prüfen, ob die Lampe im Weiß-Modus ist.
const isWhiteMode = !!currentKelvin;

let nextPayload = {};

// --- 3. Logik: Nächste Szene bestimmen ---

if (isWhiteMode) {
    // Die Lampe ist AKTUELL im Weiß-Modus.

    // Finde den Index des Weißtons, der dem aktuellen Wert am NÄCHSTEN kommt.
    // Dies löst das Problem der Ungenauigkeit (z.B. 2202K statt 2200K).
    const distances = whiteTones.map(tone => Math.abs(tone - currentKelvin));
    const minDistance = Math.min(...distances);
    const currentIndex = distances.indexOf(minDistance);

    // Prüfen, ob überhaupt Weißtöne geladen wurden
    if (whiteTones.length === 0) {
        // Fallback: Wenn keine Weißtöne definiert sind, zu Rot wechseln
        nextPayload.rgb_color = colors[0] || [255, 0, 0]; // Nimm erstes Farbe oder Rot
        msg.payload = nextPayload;
        return msg;
    }

    // Berechne den NÄCHSTEN Index in der Liste (von kalt nach warm)
    const nextIndex = (currentIndex + 1) % whiteTones.length;

    if (nextIndex === 0) {
        // Wir waren beim letzten Weißton (currentIndex war whiteTones.length - 1).
        // Der Zyklus ist komplett. Wechsle zu Farben (zu Rot).
        nextPayload.rgb_color = colors[0] || [255, 0, 0]; // Nimm erstes Farbe oder Rot
    } else {
        // Nächsten Weißton in der Liste setzen.
        nextPayload.color_temp_kelvin = whiteTones[nextIndex];
    }

} else {
    // Die Lampe ist AKTUELL im Farb-Modus (oder aus).

    // Prüfen, ob überhaupt Farben geladen wurden
    if (colors.length === 0) {
        // Fallback: Wenn keine Farben definiert sind, zu Kaltweiß wechseln
        nextPayload.color_temp_kelvin = whiteTones[0] || 6500; // Nimm erstes Weiß oder 6500K
        msg.payload = nextPayload;
        return msg;
    }

    // Wenn die Lampe aus war (kein currentRGB), starte bei Farbe 0.
    if (!currentRGB) {
        nextPayload.rgb_color = colors[0];
        msg.payload = nextPayload;
        return msg;
    }

    // Finde den Index der Farbe, die dem aktuellen Wert am NÄCHSTEN kommt.
    const distances = colors.map(c => getColorDistance(c, currentRGB));
    const minDistance = Math.min(...distances);
    const currentIndex = distances.indexOf(minDistance);

    // Berechne den NÄCHSTEN Index
    const nextIndex = (currentIndex + 1) % colors.length;

    if (nextIndex === 0) {
        // Wir waren beim letzten Farbeintrag (currentIndex war colors.length - 1).
        // Der Zyklus ist komplett. Wechsle zu Weißtönen (zum kältesten).
        nextPayload.color_temp_kelvin = whiteTones[0] || 6500; // Nimm erstes Weiß oder 6500K
    } else {
        // Nächste Farbe in der Liste setzen.
        nextPayload.rgb_color = colors[nextIndex];
    }
}

// Fügt eine Übergangszeit von 0.5 Sekunden (500ms) hinzu,
// passend zur Wiederholrate der Fernbedienung.
nextPayload.transition = 0.5;

msg.payload = nextPayload;

// Aufräumen der msg
delete msg.rgb_color;
delete msg.color_temp_kelvin;
delete msg.state;

return msg;

