const path = String(msg.path || '');
const match = path.match(/^Trigger[123] long( extended)? - false$/);

if (match) {
    msg.li_context = {
        ...(msg.li_context || {}),
        offReason: 'inactivity_timeout',
        timeoutMode: match[1] ? 'long_extended' : 'long',
        triggerPath: path
    };
}

return msg;

const PRIORITY = {
    manual_off: 120,
    timeout_off: 85,
    safety: 100,
    camera: 90,
    absence: 80,
    manual_on: 70,
    routine: 60,
    presence_automation: 50,
    comfort: 40,
    technical: 10
};

function envJson(name, fallback) {
    const value = env.get(name);
    if (value === undefined || value === null || value === '') return fallback;
    if (typeof value === 'object') return value;
    try { return JSON.parse(value); } catch (error) { return fallback; }
}

function envString(name, fallback = '') {
    const value = env.get(name);
    return value === undefined || value === null ? fallback : String(value);
}

function toArray(value) {
    if (Array.isArray(value)) return value;
    if (value === undefined || value === null || value === '') return [];
    return [value];
}

function uniqueStrings(values) {
    return [...new Set(values.filter(value => typeof value === 'string' && value.length > 0))];
}

function isPlaceholderEntity(value) {
    return /^input_(number|boolean)\.allgemein_immer_[01]$/.test(value);
}

function readPath(root, path) {
    return String(path).split('.').reduce((current, key) => current === undefined ? undefined : current?.[key], root);
}

function getFlowPath(path, minParentDepth = 0) {
    const cleanPath = String(path || '').trim().replace(/^flow\./, '');
    for (let depth = minParentDepth; depth <= 5; depth++) {
        const prefix = depth === 0 ? '' : '$parent.'.repeat(depth);
        const value = flow.get(prefix + cleanPath);
        if (value !== undefined && value !== null && value !== '') return value;
    }
    return undefined;
}

function inferRoomFromAutomationEntity() {
    const entityId = toArray(getFlowPath('licht.automatisierung_name_lichtanforderung', 1))[0];
    const match = typeof entityId === 'string'
        ? entityId.match(/^input_select\.licht_automatisierung_(.+)_lichtanforderung$/)
        : null;
    return match ? match[1] : '';
}

function roomLightTargets() {
    const paths = [
        'licht.automatisierung_lichtgruppe',
        'licht.automatisierung_dimmgruppe',
        'licht.automatisierung_farbgruppe'
    ];
    for (let index = 1; index <= 20; index++) {
        paths.push('licht.automatisierung_licht' + index);
    }

    return uniqueStrings(paths
        .flatMap(path => toArray(getFlowPath(path, 0)))
        .filter(value => value.startsWith('light.'))
        .filter(value => !isPlaceholderEntity(value)));
}

function resolveTemplate(value) {
    if (Array.isArray(value)) return value.map(resolveTemplate);
    if (typeof value !== 'string') return value;
    if (value === '$roomLightTargets') return roomLightTargets();

    const parentMatch = value.match(/^{{\s*flow\.\$parent\.([^}]+)\s*}}$/);
    if (parentMatch) return getFlowPath(parentMatch[1], 1);

    const flowMatch = value.match(/^{{\s*flow\.([^}]+)\s*}}$/);
    if (flowMatch) return getFlowPath(flowMatch[1], 0);

    const msgMatch = value.match(/^{{\s*msg\.([^}]+)\s*}}$/) || value.match(/^{{\s*([^}]+)\s*}}$/);
    if (msgMatch) return readPath(msg, msgMatch[1].trim().replace(/^msg\./, ''));

    if (value.startsWith('flow.$parent.')) return getFlowPath(value.slice('flow.$parent.'.length), 1);
    if (value.startsWith('flow.')) return getFlowPath(value.slice('flow.'.length), 0);
    if (value.startsWith('msg.')) return readPath(msg, value.slice('msg.'.length));

    return value;
}

function normalizeEntities(values) {
    const list = toArray(values);
    return uniqueStrings(list
        .map(resolveTemplate)
        .flatMap(value => Array.isArray(value) ? value : [value])
        .filter(value => typeof value === 'string' && value.length > 0)
        .filter(value => !value.includes('{{'))
        .filter(value => !isPlaceholderEntity(value)));
}

function buildData(config, request) {
    if (request && Object.prototype.hasOwnProperty.call(request, 'data')) return request.data || {};
