    .join(" ");

msg.notification_message = "Festplatte " + driveName + " hat einen Fehler!";
return msg;

const CONFIG = {
    sites: {
        alt: { matchStates: ['home', 'Zu Hause (33)', '33', '33a'] },
        neu: { matchStates: [] }
    },
    timings: {
        acStabilizeMs: 15 * 60 * 1000,
        locationWaitMs: 15 * 60 * 1000,
        startWatchdogMs: 6 * 60 * 1000,
        lowPowerConfirmMs: 30 * 1000,
        s90PostStopMeasureMs: 6 * 60 * 1000,
        notificationDedupeMs: 5 * 60 * 1000
    },
    powerLowThresholdW: 100,
    chargePoints: {
