            power: '',
            verifySwitchDelayMs: 2500
        }
    },
    vehicles: {
        s90: {
            enabled: true,
            label: 'Volvo S90',
            strategy: 'time_estimate',
            defaultPointBySite: { alt: 'alt_s90', neu: 'neu_shared' },
            notifications: {
                celine: 'input_boolean.benachrichtigung_volvo_s90_ladeautomatik_celine',
                jens: 'input_boolean.benachrichtigung_volvo_s90_ladeautomatik_jens'
            },
            entities: {
                automation: 'input_boolean.fahrzeug_volvo_s90_ladeautomatik',
                active: 'input_boolean.fahrzeug_volvo_s90_ladeautomatik_aktiv',
                battery: 'sensor.volvo_s90_batterie',
                targetSoc: 'input_number.fahrzeug_volvo_s90_maximalladestand',
                minDiff: 'input_number.fahrzeug_volvo_s90_minimalladeunterschied',
                minBattery: 'input_number.fahrzeug_volvo_s90_mindestbatteriestand',
                chargeType: 'sensor.volvo_s90_ladetyp',
                chargeStatus: 'sensor.volvo_s90_ladestatus',
                location: 'device_tracker.volvo_s90_standort',
                engine: 'binary_sensor.volvo_s90_motorstatus',
