            label: 'Volvo XC90',
            strategy: 'target_soc_wait',
            defaultPointBySite: { alt: 'alt_xc90', neu: 'neu_shared' },
            notifications: {
                andrea: 'input_boolean.benachrichtigung_33a_volvo_xc90_ladeautomatik_andrea',
                fred: 'input_boolean.benachrichtigung_33a_volvo_xc90_ladeautomatik_fred',
                jens: 'input_boolean.benachrichtigung_volvo_xc90_ladeautomatik_jens'
            },
            entities: {
                automation: 'input_boolean.fahrzeug_volvo_xc90_ladeautomatik',
                active: 'input_boolean.fahrzeug_volvo_xc90_ladeautomatik_aktiv',
                battery: 'sensor.volvo_xc90_batterie',
                targetSoc: 'input_number.fahrzeug_volvo_xc90_maximalladestand',
                minDiff: 'input_number.fahrzeug_volvo_xc90_minimalladeunterschied',
                minBattery: 'input_number.fahrzeug_volvo_xc90_mindestbatteriestand',
                chargeType: 'sensor.volvo_xc90_ladetyp',
                chargeStatus: 'sensor.volvo_xc90_ladestatus',
                location: 'device_tracker.volvo_xc90_standort',
                engine: 'binary_sensor.volvo_xc90_motorstatus',
                durationConstant: 'input_number.fahrzeug_volvo_xc90_ladedauerkonstante',
                eta: 'input_text.fahrzeug_volvo_xc90_ladeautomatik_eta'
            }
        }
    }
};

const CONTEXT_KEY = 'fahrzeugLadeautomatik.state';
const requested = msg.fahrzeug_laden || {};
const dryRun = requested.dry_run === true || msg.dry_run === true;
const now = Date.now();
const outputs = [[], [], [], [], []];

function toArray(value) {
    if (Array.isArray(value)) return value;
    if (value === undefined || value === null || value === '') return [];
    return [value];
}

function haStates() {
    const ha = global.get('homeassistant');
    return ha?.homeAssistant?.states || ha?.states || {};
}

const states = haStates();

function state(entityId) {
    if (!entityId) return undefined;
    return states?.[entityId]?.state;
}

function numberState(entityId) {
    const value = state(entityId);
    const parsed = Number(String(value).replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : null;
}

function isOnState(value) {
    return ['on', 'true', 'home'].includes(String(value).toLowerCase());
}

function isOn(entityId) {
    return isOnState(state(entityId));
}

function isUnavailable(value) {
    return value === undefined || value === null || value === '' || ['unknown', 'unavailable'].includes(String(value).toLowerCase());
}

function isAc(value) {
    const text = String(value || '').toLowerCase();
    return text === 'ac' || text.includes('ac');
}

function isCharging(value) {
    return String(value || '').toLowerCase() === 'charging';
}

function cleanNumber(value, fallback = null) {
    const parsed = Number(String(value).replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : fallback;
}

function formattedTime(timestamp) {
    const date = new Date(timestamp);
    return date.getHours().toString().padStart(2, '0') + ':' + date.getMinutes().toString().padStart(2, '0');
}

function formatDuration(minutes) {
    const safe = Math.max(0, Number(minutes) || 0);
    const hours = Math.floor(safe / 60);
    const mins = Math.round(safe % 60);
    return hours + ':' + mins.toString().padStart(2, '0') + 'h';
}

function readRuntime() {
    const runtime = flow.get(CONTEXT_KEY);
    const normalized = runtime && typeof runtime === 'object' ? runtime : {};
    normalized.active = normalized.active || null;
    normalized.queue = Array.isArray(normalized.queue) ? normalized.queue : [];
    normalized.pending = normalized.pending && typeof normalized.pending === 'object' ? normalized.pending : {};
    normalized.recentNotifications = normalized.recentNotifications && typeof normalized.recentNotifications === 'object' ? normalized.recentNotifications : {};
    return normalized;
}

const runtime = readRuntime();

function writeRuntime() {
    runtime.updatedAt = new Date(now).toISOString();
    if (!dryRun) flow.set(CONTEXT_KEY, runtime);
}

function finishReturn() {
    writeRuntime();
    return outputs.map((items) => items.length ? items : null);
}

function token(prefix) {
    return prefix + '-' + now.toString(36) + '-' + Math.random().toString(16).slice(2, 10);
}

function diagnose(level, event, reason, details = {}) {
    outputs[1].push({
        _msgid: msg._msgid,
        diagnose: {
            level,
            domain: 'F',
            flow: 'F - Ladeautomatik',
            event,
            source: 'F - Ladeautomatik',
            target: details.vehicle || requested.vehicle || '-',
            reason,
            message: event + ': ' + reason,
            details,
            correlation_id: requested.correlation_id || msg._msgid
        }
    });
}

function vehicleConfig(vehicleKey) {
    return CONFIG.vehicles[vehicleKey] || null;
}

function detectSite(vehicle) {
    const locationState = state(vehicle.entities.location);
    if (isUnavailable(locationState)) return 'unknown';
    for (const [site, config] of Object.entries(CONFIG.sites)) {
        if (toArray(config.matchStates).includes(locationState)) return site;
    }
    return 'unknown';
}

function choosePoint(vehicleKey, site, explicitPoint) {
    const vehicle = vehicleConfig(vehicleKey);
    if (!vehicle) return null;
    if (explicitPoint) return CONFIG.chargePoints[explicitPoint] ? explicitPoint : null;
    const preferred = vehicle.defaultPointBySite?.[site];
    if (preferred && CONFIG.chargePoints[preferred]) return preferred;
    const fallback = Object.entries(CONFIG.chargePoints).find(([, point]) => point.enabled && point.site === site && point.vehicles.includes(vehicleKey));
    return fallback?.[0] || null;
}

function snapshot(vehicleKey, explicitPoint) {
    const vehicle = vehicleConfig(vehicleKey);
    if (!vehicle) return null;
    const site = detectSite(vehicle);
    const chargePoint = choosePoint(vehicleKey, site, explicitPoint);
    const point = chargePoint ? CONFIG.chargePoints[chargePoint] : null;
    const soc = numberState(vehicle.entities.battery);
    const targetSoc = numberState(vehicle.entities.targetSoc);
    const minDiff = numberState(vehicle.entities.minDiff);
    const durationConstantRaw = numberState(vehicle.entities.durationConstant);
    const durationConstant = durationConstantRaw && durationConstantRaw > 0 ? durationConstantRaw : 2.4;
    const chargeType = String(state(vehicle.entities.chargeType) || '');
    const chargeStatus = String(state(vehicle.entities.chargeStatus) || '');
    const power = point?.power ? numberState(point.power) : null;
    return {
        vehicle: vehicleKey,
        label: vehicle.label,
        strategy: vehicle.strategy,
        site,
        location: state(vehicle.entities.location),
        chargePoint,
        point,
        soc,
        targetSoc,
        minDiff,
        durationConstant,
        chargeType,
        chargeStatus,
        connectedAc: isAc(chargeType),
        charging: isCharging(chargeStatus),
        automation: state(vehicle.entities.automation),
        automationOn: isOn(vehicle.entities.automation),
        engine: state(vehicle.entities.engine),
        engineOn: isOn(vehicle.entities.engine),
        activeHelper: state(vehicle.entities.active),
        power,
        remaining: targetSoc !== null && soc !== null ? targetSoc - soc : null
    };
}

function allVehicleSnapshots() {
    return Object.keys(CONFIG.vehicles).map((key) => snapshot(key)).filter(Boolean);
}

function removeFromQueue(vehicleKey) {
    runtime.queue = runtime.queue.filter((entry) => entry.vehicle !== vehicleKey);
}

function enqueue(snap, reason) {
    removeFromQueue(snap.vehicle);
    runtime.queue.push({
        vehicle: snap.vehicle,
        site: snap.site,
        chargePoint: snap.chargePoint,
        reason,
        queuedAt: new Date(now).toISOString()
    });
    diagnose('info', 'queued', reason, { ...snap, queueLength: runtime.queue.length });
}

function dequeueNextValid() {
    while (runtime.queue.length) {
        const next = runtime.queue.shift();
        const snap = snapshot(next.vehicle, next.chargePoint);
        if (!snap) continue;
        const check = startCheck(snap, false);
        if (check.ok) return { snap, reason: 'FIFO nach vorherigem Ladevorgang' };
        diagnose('info', 'queue_entry_dropped', check.reason, { ...snap, queued: next });
    }
    return null;
}

function buildEstimate(snap) {
    const minutes = Math.max(0, (snap.targetSoc - snap.soc) * snap.durationConstant);
    const etaTimestamp = now + minutes * 60 * 1000;
    const durationText = formatDuration(minutes);
    const etaText = 'ETA: ' + formattedTime(etaTimestamp) + ' Uhr.';
    return {
        minutes,
        durationText,
        eta: etaText,
        startMessage: 'Ladung gestartet. Berechnete Ladedauer: ' + durationText + '. ETA: ' + formattedTime(etaTimestamp) + ' Uhr.'
    };
}

function notificationState(vehicleKey) {
    const vehicle = vehicleConfig(vehicleKey);
    const result = {};
    for (const [key, entityId] of Object.entries(vehicle.notifications || {})) {
        result[key] = state(entityId);
    }
    return result;
}

function notify(vehicleKey, event, message) {
    const key = vehicleKey + '|' + event + '|' + message;
    for (const [recentKey, timestamp] of Object.entries(runtime.recentNotifications)) {
        if (now - timestamp > CONFIG.timings.notificationDedupeMs) delete runtime.recentNotifications[recentKey];
    }
    if (runtime.recentNotifications[key]) {
        diagnose('debug', 'notification_deduped', 'Benachrichtigung wurde gedrosselt', { vehicle: vehicleKey, event, message });
        return;
    }
    runtime.recentNotifications[key] = now;
    if (dryRun) {
        diagnose('info', 'dry_run_notification', 'Benachrichtigung im Dry-Run unterdrueckt', { vehicle: vehicleKey, event, message });
        return;
    }
    outputs[3].push({
        ...notificationState(vehicleKey),
        info_text: message,
        benachrichtigung: {
            title: 'Fahrzeug',
            message,
            data: {
                tag: 'fahrzeug-ladeautomatik-' + vehicleKey,
                ttl: 0,
                priority: 'high'
            }
        },
        fahrzeug_laden: {
            vehicle: vehicleKey,
            event
        }
    });
}

const HELPER_ALLOWLIST = new Set(Object.values(CONFIG.vehicles).flatMap((vehicle) => [
    vehicle.entities.active,
    vehicle.entities.eta,
    vehicle.entities.durationConstant
]));

function helperAction(action, entityId, data, reason, details = {}) {
    if (!HELPER_ALLOWLIST.has(entityId)) {
        diagnose('warning', 'helper_action_rejected', 'Helper Entity ist nicht erlaubt', { entityId, action, data, ...details });
        return;
    }
    diagnose('info', 'helper_action', reason || action + ' ' + entityId, { entityId, action, data, ...details });
    if (dryRun) return;
    outputs[2].push({
        topic: 'f/ladeautomatik/helper/' + action,
        payload: {
            action,
            target: { entity_id: [entityId] },
            data: data || {}
        },
        helper_action: { action, entityId, data: data || {}, reason },
        fahrzeug_laden: details.fahrzeug_laden || { vehicle: details.vehicle || requested.vehicle || null }
    });
}

function steRequest(intent, actions, decision) {
    if (!actions.length) return;
    if (dryRun) {
        diagnose('info', 'dry_run_ste_action', 'STE-Aktionen im Dry-Run unterdrueckt', { intent, actions, decision });
        return;
    }
    outputs[0].push({
        ste: {
            source: 'F - Ladeautomatik',
            intent,
            actions,
            correlation_id: requested.correlation_id || msg._msgid,
            decision,
            requested_at: new Date(now).toISOString()
        },
        fahrzeug_laden: {
            vehicle: decision.vehicle || null,
            site: decision.site || 'unknown',
            charge_point: decision.chargePoint || null,
            state: decision.state || 'idle',
            reason: decision.reason || ''
        }
    });
}

function delayEvent(vehicleKey, event, delayMs, eventToken, details = {}) {
    if (dryRun) {
        diagnose('info', 'dry_run_delay', 'Delay im Dry-Run nicht geplant', { vehicle: vehicleKey, event, delayMs, token: eventToken });
        return;
    }
    outputs[4].push({
        payload: event,
        delay: Math.max(1, Math.round(delayMs)),
        fahrzeug_laden: {
            vehicle: vehicleKey,
            event,
            internal: true,
            token: eventToken,
            correlation_id: requested.correlation_id || msg._msgid,
            details
        }
    });
}

function buildStopActions(active, reason) {
    const actions = [];
    for (const [pointKey, point] of Object.entries(CONFIG.chargePoints)) {
        if (!point.enabled || !point.switch) continue;
        actions.push({
            action: 'switch.turn_off',
            entityId: point.switch,
            priority: pointKey === active?.chargePoint ? 100 : 90,
            reason,
            verify: [{ entityId: point.switch, comparator: 'eq', expected: 'off', delayMs: point.verifySwitchDelayMs || 2500 }]
        });
    }
    return actions;
}

function buildStartActions(chargePointKey, reason) {
    const selected = CONFIG.chargePoints[chargePointKey];
    const actions = [];
    for (const [pointKey, point] of Object.entries(CONFIG.chargePoints)) {
        if (!point.enabled || !point.switch || pointKey === chargePointKey) continue;
        actions.push({
            action: 'switch.turn_off',
            entityId: point.switch,
            priority: 100,
            reason: 'Verriegelung vor Start von ' + chargePointKey,
            verify: [{ entityId: point.switch, comparator: 'eq', expected: 'off', delayMs: point.verifySwitchDelayMs || 2500 }]
        });
    }
    actions.push({
        action: 'switch.turn_on',
        entityId: selected.switch,
        priority: 80,
        reason,
        verify: [{ entityId: selected.switch, comparator: 'eq', expected: 'on', delayMs: selected.verifySwitchDelayMs || 2500 }]
    });
    return actions;
}

function startCheck(snap, override) {
    if (!snap) return { ok: false, reason: 'unbekanntes Fahrzeug' };
    const vehicle = vehicleConfig(snap.vehicle);
    if (!vehicle?.enabled) return { ok: false, reason: 'Fahrzeug ist deaktiviert' };
    if (!snap.automationOn && !override) return { ok: false, reason: 'Ladeautomatik ist deaktiviert' };
    if (snap.engineOn) return { ok: false, reason: 'Motor ist eingeschaltet' };
    if (snap.site === 'unknown' || !CONFIG.sites[snap.site]) return { ok: false, reason: 'Standort ist unbekannt oder nicht konfiguriert', waitLocation: true };
    if (!snap.chargePoint || !snap.point || !snap.point.enabled || !snap.point.switch) return { ok: false, reason: 'Ladepunkt ist nicht konfiguriert oder deaktiviert' };
    if (!snap.point.vehicles.includes(snap.vehicle)) return { ok: false, reason: 'Fahrzeug ist am Ladepunkt nicht erlaubt' };
    if (snap.soc === null || snap.targetSoc === null || snap.minDiff === null) return { ok: false, reason: 'ungueltiger Batterie- oder Zielwert' };
    if (!snap.connectedAc && !override) return { ok: false, reason: 'kein AC-Ladekabel erkannt' };
    if (!(snap.soc <= snap.targetSoc && (snap.targetSoc - snap.soc) > snap.minDiff) && !override) {
        return { ok: false, reason: 'Ladeunterschied kleiner als Mindestwert' };
    }
    return { ok: true, reason: 'Startbedingung erfuellt' };
}

function clearVehicleWork(vehicleKey) {
    removeFromQueue(vehicleKey);
    delete runtime.pending[vehicleKey];
}

function scheduleLocationWait(snap) {
    const existing = runtime.pending[snap.vehicle];
    if (existing?.phase === 'waiting_location') {
        diagnose('debug', 'location_wait_active', 'Standort-Wartezeit laeuft bereits', { ...snap, pending: existing });
        return;
    }
    const eventToken = token('loc-' + snap.vehicle);
    runtime.pending[snap.vehicle] = { phase: 'waiting_location', token: eventToken, createdAt: now, chargePoint: snap.chargePoint };
    diagnose('info', 'waiting_location', 'Standort ist unbekannt, warte auf gueltigen Standort', { ...snap, token: eventToken });
    delayEvent(snap.vehicle, 'location_wait_elapsed', CONFIG.timings.locationWaitMs, eventToken);
}

function scheduleStabilization(snap) {
    const existing = runtime.pending[snap.vehicle];
    if (existing?.phase === 'stabilizing_ac') {
        diagnose('debug', 'stabilizing_ac_active', 'AC-Stabilisierung laeuft bereits', { ...snap, pending: existing });
        return;
    }
    const eventToken = token('ac-' + snap.vehicle);
    runtime.pending[snap.vehicle] = { phase: 'stabilizing_ac', token: eventToken, createdAt: now, chargePoint: snap.chargePoint };
    diagnose('info', 'stabilizing_ac', 'AC-Verbindung erkannt, warte 15 Minuten vor Start', { ...snap, token: eventToken });
    delayEvent(snap.vehicle, 'stabilization_elapsed', CONFIG.timings.acStabilizeMs, eventToken);
}

function beginStart(snap, reason, options = {}) {
    const override = options.override === true;
    const active = runtime.active;
    if (active && active.vehicle !== snap.vehicle && !override) {
        enqueue(snap, 'anderes Fahrzeug laedt bereits');
        return;
    }

    const estimate = buildEstimate(snap);
    const eventToken = token('charge-' + snap.vehicle);
    const actions = [];

    if (active && active.vehicle !== snap.vehicle && override) {
        actions.push(...buildStopActions(active, 'Override ersetzt aktiven Ladevorgang'));
        helperAction('input_boolean.turn_off', vehicleConfig(active.vehicle).entities.active, {}, 'Aktiv-Status wegen Override ausschalten', { vehicle: active.vehicle });
        notify(active.vehicle, 'charge_aborted', 'Ladevorgang abgebrochen.');
        diagnose('warning', 'override', 'Override ersetzt aktiven Ladevorgang', { previousActive: active, next: snap });
    }

    actions.push(...buildStartActions(snap.chargePoint, reason));
    runtime.active = {
        vehicle: snap.vehicle,
        phase: 'pending_start',
        site: snap.site,
        chargePoint: snap.chargePoint,
        token: eventToken,
        requestedAt: now,
        startedAt: null,
        startSoc: snap.soc,
        targetSoc: snap.targetSoc,
        minDiff: snap.minDiff,
        chargingConstant: snap.durationConstant,
        estimatedMinutes: estimate.minutes,
        reason
    };
    delete runtime.pending[snap.vehicle];
    removeFromQueue(snap.vehicle);

    steRequest('vehicle_charge_start', actions, { ...snap, state: 'pending_start', reason, estimatedMinutes: estimate.minutes });
    helperAction('input_text.set_value', vehicleConfig(snap.vehicle).entities.eta, { value: estimate.eta }, 'ETA setzen', { vehicle: snap.vehicle });
    notify(snap.vehicle, 'charge_start', estimate.startMessage);
    delayEvent(snap.vehicle, 'start_watchdog_elapsed', CONFIG.timings.startWatchdogMs, eventToken);
    diagnose('info', 'charge_start', reason, { ...snap, token: eventToken, estimatedMinutes: estimate.minutes });
}

function markCharging(snap, reason) {
    const active = runtime.active;
    if (!active || active.vehicle !== snap.vehicle) {
        const estimate = buildEstimate(snap);
        runtime.active = {
            vehicle: snap.vehicle,
            phase: 'charging',
            site: snap.site,
            chargePoint: snap.chargePoint,
            token: token('adopt-' + snap.vehicle),
            requestedAt: now,
            startedAt: now,
            startSoc: snap.soc,
            targetSoc: snap.targetSoc,
            minDiff: snap.minDiff,
            chargingConstant: snap.durationConstant,
            estimatedMinutes: estimate.minutes,
            reason: reason || 'Ladestatus charging erkannt'
        };
    } else {
        active.phase = 'charging';
        active.startedAt = active.startedAt || now;
        active.startSoc = active.startSoc ?? snap.soc;
        active.targetSoc = snap.targetSoc ?? active.targetSoc;
        active.chargingConstant = snap.durationConstant || active.chargingConstant || 2.4;
        active.estimatedMinutes = active.estimatedMinutes ?? buildEstimate(snap).minutes;
    }
    const current = runtime.active;
    helperAction('input_boolean.turn_on', vehicleConfig(snap.vehicle).entities.active, {}, 'Aktiv-Status einschalten', { vehicle: snap.vehicle });
    diagnose('info', 'charge_confirmed', reason || 'Ladevorgang laeuft', { ...snap, active: current });
    if (snap.strategy === 'time_estimate' && current.estimatedMinutes > 0) {
        delayEvent(snap.vehicle, 'charge_timer_elapsed', current.estimatedMinutes * 60 * 1000, current.token, { estimatedMinutes: current.estimatedMinutes });
    }
}

function updateChargingConstant(snap, active, durationMinutes, aborted) {
    if (aborted || !snap || snap.soc === null) return;
    const vehicle = vehicleConfig(active.vehicle);
    let next = cleanNumber(active.chargingConstant, snap.durationConstant || 2.4);
    const before = next;
    if (vehicle.strategy === 'time_estimate') {
        if (snap.soc > active.targetSoc) next -= 0.05;
        if (snap.soc < active.targetSoc) next += 0.05;
    } else {
        const estimated = cleanNumber(active.estimatedMinutes, null);
        if (estimated === null || durationMinutes === null) return;
        if (estimated > durationMinutes) next -= 0.05;
        if (estimated < durationMinutes) next += 0.05;
    }
    next = Math.max(0.1, Math.round(next * 100) / 100);
    if (next !== before) {
        helperAction('input_number.set_value', vehicle.entities.durationConstant, { value: next }, 'Ladedauerkonstante anpassen', {
            vehicle: active.vehicle,
            before,
            after: next,
            durationMinutes,
            soc: snap.soc,
            targetSoc: active.targetSoc
        });
    }
}

function maybeStartNext() {
    const next = dequeueNextValid();
    if (next) beginStart(next.snap, next.reason, { skipStabilization: true });
}

function completeActive(reason, options = {}) {
    const active = runtime.active;
    if (!active) return;
    const vehicle = vehicleConfig(active.vehicle);
    const snap = snapshot(active.vehicle, active.chargePoint) || { vehicle: active.vehicle };
    const aborted = options.aborted === true;
    const includeStopActions = options.includeStopActions !== false;
    const durationMinutes = active.startedAt ? (now - active.startedAt) / 60000 : cleanNumber(active.estimatedMinutes, 0);

    if (includeStopActions) {
        steRequest('vehicle_charge_stop', buildStopActions(active, reason), { ...snap, state: aborted ? 'aborted' : 'finished', reason });
    }
    helperAction('input_boolean.turn_off', vehicle.entities.active, {}, 'Aktiv-Status ausschalten', { vehicle: active.vehicle });
    updateChargingConstant(snap, active, durationMinutes, aborted);
    notify(active.vehicle, aborted ? 'charge_aborted' : 'charge_finished', aborted ? 'Ladevorgang abgebrochen.' : 'Fuer ' + formatDuration(durationMinutes) + ' geladen. (' + (snap.soc ?? '-') + '%)');
    diagnose(aborted ? 'warning' : 'info', aborted ? 'charge_aborted' : 'charge_finished', reason, { ...snap, active, durationMinutes });
    runtime.active = null;
    clearVehicleWork(active.vehicle);
    maybeStartNext();
}

function startS90PostStop(reason) {
    const active = runtime.active;
    if (!active) return;
    active.phase = 'post_stop_wait';
    steRequest('vehicle_charge_stop', buildStopActions(active, reason), { vehicle: active.vehicle, site: active.site, chargePoint: active.chargePoint, state: 'stopping', reason });
    diagnose('info', 'charge_stopping', reason, { active });
    delayEvent(active.vehicle, 'post_stop_measure_elapsed', CONFIG.timings.s90PostStopMeasureMs, active.token);
}

function schedulePowerRecheck(snap) {
    const active = runtime.active;
    if (!active || active.phase !== 'charging') return;
    if (active.lowPower?.token) {
        diagnose('debug', 'power_low_pending', 'Niedrigleistungs-Pruefung laeuft bereits', { ...snap, active });
        return;
    }
    const eventToken = token('power-' + snap.vehicle);
    active.lowPower = { token: eventToken, firstSeenAt: now, power: snap.power };
    diagnose('warning', 'power_low_candidate', 'Ladeleistung <= ' + CONFIG.powerLowThresholdW + 'W, pruefe erneut', { ...snap, token: eventToken });
    delayEvent(snap.vehicle, 'power_low_recheck', CONFIG.timings.lowPowerConfirmMs, eventToken);
}

function handleActiveVehicle(snap) {
    const active = runtime.active;
    if (!active || active.vehicle !== snap.vehicle) return false;

    if (active.phase === 'pending_start') {
        if (snap.charging) {
            markCharging(snap, 'Ladestatus charging erkannt');
            return true;
        }
        if (snap.engineOn) {
            completeActive('Motor ist eingeschaltet', { aborted: true });
            return true;
        }
        if (!snap.connectedAc) {
            completeActive('AC-Ladekabel getrennt', { aborted: true });
            return true;
        }
        return true;
    }

    if (active.phase === 'post_stop_wait') return true;
    if (active.phase !== 'charging') return true;

    if (snap.engineOn) {
        completeActive('Motor ist eingeschaltet', { aborted: true });
        return true;
    }
    if (!snap.connectedAc) {
        completeActive('AC-Ladekabel getrennt', { aborted: true });
        return true;
    }
    if (snap.chargeStatus && !snap.charging) {
        completeActive('Ladestatus nicht charging', { aborted: true });
        return true;
    }
    if (snap.soc !== null && active.targetSoc !== undefined && snap.soc >= active.targetSoc) {
        completeActive('Zielladestand erreicht', { aborted: false });
        return true;
    }
    if (snap.power !== null && snap.power <= CONFIG.powerLowThresholdW) {
        schedulePowerRecheck(snap);
        return true;
    }
    if (active.lowPower) {
        diagnose('info', 'power_low_cleared', 'Ladeleistung wieder ueber Schwelle', { ...snap, lowPower: active.lowPower });
        delete active.lowPower;
    }
    return true;
}

function evaluateVehicle(vehicleKey, options = {}) {
    const snap = snapshot(vehicleKey, requested.charge_point);
    if (!snap) {
        diagnose('warning', 'request_rejected', 'unbekanntes oder fehlendes Fahrzeug', { vehicle: vehicleKey, requested });
        return;
    }

    if (dryRun) {
        const check = startCheck(snap, requested.override === true);
        diagnose('info', 'dry_run_decision', check.ok ? 'Start waere moeglich' : check.reason, { ...snap, check, runtime });
        return;
    }

    if (!snap.automationOn && requested.override !== true) {
        if (runtime.active?.vehicle === snap.vehicle) {
            completeActive('Ladeautomatik ist deaktiviert', { aborted: true });
        } else {
            clearVehicleWork(snap.vehicle);
            helperAction('input_boolean.turn_off', vehicleConfig(snap.vehicle).entities.active, {}, 'Aktiv-Status ausschalten', { vehicle: snap.vehicle });
            diagnose('info', 'request_ignored', 'Ladeautomatik ist deaktiviert', snap);
        }
        return;
    }

    if (handleActiveVehicle(snap)) return;

    if (snap.charging && snap.connectedAc) {
        if (runtime.active && runtime.active.vehicle !== snap.vehicle && requested.override !== true) {
            enqueue(snap, 'anderes Fahrzeug laedt bereits');
            return;
        }
        markCharging(snap, 'laufenden Ladevorgang uebernommen');
        return;
    }

    const check = startCheck(snap, requested.override === true);
    if (!check.ok) {
        if (check.waitLocation && snap.connectedAc && snap.automationOn && !snap.engineOn) {
            scheduleLocationWait(snap);
        } else {
            clearVehicleWork(snap.vehicle);
            diagnose(check.reason.includes('deaktiviert') ? 'info' : 'warning', 'request_ignored', check.reason, snap);
        }
        return;
    }

    if (runtime.active && runtime.active.vehicle !== snap.vehicle && requested.override !== true) {
        if (options.fromStabilization === true) enqueue(snap, 'anderes Fahrzeug laedt bereits');
        else scheduleStabilization(snap);
        return;
    }

    if (options.fromStabilization === true || requested.override === true || options.skipStabilization === true) {
        beginStart(snap, requested.override === true ? 'Override' : 'Startbedingung erfuellt', { override: requested.override === true });
    } else {
        scheduleStabilization(snap);
    }
}

function handleDelayed() {
    const vehicleKey = requested.vehicle;
    const event = requested.event;
    const eventToken = requested.token;
    if (!vehicleKey || !eventToken) {
        diagnose('warning', 'delayed_event_invalid', 'interner Delay ohne Fahrzeug oder Token', { requested });
        return;
    }

    const pending = runtime.pending[vehicleKey];
    const active = runtime.active;

    if (event === 'location_wait_elapsed') {
        if (!pending || pending.phase !== 'waiting_location' || pending.token !== eventToken) {
            diagnose('debug', 'stale_token_ignored', 'veralteter Standort-Token ignoriert', { vehicle: vehicleKey, token: eventToken, pending });
            return;
        }
        delete runtime.pending[vehicleKey];
        evaluateVehicle(vehicleKey, { fromLocationWait: true });
        return;
    }

    if (event === 'stabilization_elapsed') {
        if (!pending || pending.phase !== 'stabilizing_ac' || pending.token !== eventToken) {
            diagnose('debug', 'stale_token_ignored', 'veralteter AC-Stabilisierungs-Token ignoriert', { vehicle: vehicleKey, token: eventToken, pending });
            return;
        }
        delete runtime.pending[vehicleKey];
        evaluateVehicle(vehicleKey, { fromStabilization: true });
        return;
    }

    if (!active || active.vehicle !== vehicleKey) {
        diagnose('debug', 'stale_token_ignored', 'veralteter Aktiv-Token ignoriert', { vehicle: vehicleKey, event, token: eventToken, active });
        return;
    }

    const snap = snapshot(vehicleKey, active.chargePoint);
    if (event === 'power_low_recheck') {
        if (!active.lowPower || active.lowPower.token !== eventToken) {
            diagnose('debug', 'stale_token_ignored', 'veralteter Power-Token ignoriert', { vehicle: vehicleKey, token: eventToken, active });
            return;
        }
        if (snap?.power !== null && snap.power <= CONFIG.powerLowThresholdW) {
            completeActive('Ladeleistung <= ' + CONFIG.powerLowThresholdW + 'W', { aborted: true });
        } else {
            delete active.lowPower;
            diagnose('info', 'power_low_cleared', 'Ladeleistung wieder ueber Schwelle', snap || { vehicle: vehicleKey });
        }
        return;
    }

    if (active.token !== eventToken) {
        diagnose('debug', 'stale_token_ignored', 'veralteter Aktiv-Token ignoriert', { vehicle: vehicleKey, event, token: eventToken, active });
        return;
    }

    if (event === 'start_watchdog_elapsed') {
        if (snap?.charging) markCharging(snap, 'Watchdog bestaetigt charging');
        else completeActive('Start-Watchdog: kein charging erkannt', { aborted: true });
        return;
    }
    if (event === 'charge_timer_elapsed') {
        startS90PostStop('Berechnete Ladedauer erreicht');
        return;
    }
    if (event === 'post_stop_measure_elapsed') {
        completeActive('Berechnete Ladedauer erreicht', { aborted: false, includeStopActions: false });
        return;
    }
}

function handleStatus(vehicleKey) {
    if (vehicleKey) {
        diagnose('info', 'status', 'Status der Ladeautomatik', { vehicle: vehicleKey, snapshot: snapshot(vehicleKey), runtime });
    } else {
        diagnose('info', 'status', 'Status der Ladeautomatik', { snapshots: allVehicleSnapshots(), runtime });
    }
}

function handleResync(reason) {
    runtime.queue = [];
    runtime.pending = {};
    const charging = allVehicleSnapshots().filter((snap) => snap.automationOn && snap.connectedAc && snap.charging && !snap.engineOn && snap.site !== 'unknown');
    if (charging.length === 1) {
        const snap = charging[0];
        runtime.active = null;
        markCharging(snap, reason || 'Resync hat laufenden Ladevorgang erkannt');
        helperAction('input_boolean.turn_off', vehicleConfig(snap.vehicle === 's90' ? 'xc90' : 's90').entities.active, {}, 'Nicht aktives Fahrzeug zuruecksetzen', { vehicle: snap.vehicle === 's90' ? 'xc90' : 's90' });
    } else {
        const previous = runtime.active;
        runtime.active = null;
        for (const vehicleKey of Object.keys(CONFIG.vehicles)) {
            helperAction('input_boolean.turn_off', vehicleConfig(vehicleKey).entities.active, {}, 'Aktiv-Status bei Resync ausschalten', { vehicle: vehicleKey });
        }
        diagnose(charging.length > 1 ? 'warning' : 'info', 'resync', reason || 'Runtime zurueckgesetzt', { previous, charging });
    }
}

