    if (action === 'light.turn_off') return 'off';
    if (action === 'light.toggle') return previousState === 'on' ? 'off' : 'on';
    return previousState || 'unknown';
}

function actionKey(action) {
    return [action.action, action.domain, action.service, stableStringify(action.data || {})].join('|');
}

function diagnosticLevel(status) {
    if (status === 'accepted' || status === 'emitted') return 'info';
    if (status === 'deduplicated') return 'debug';
    if (status === 'rejected_lower_priority') return 'info';
    if (status === 'rejected_invalid' || status === 'rejected') return 'warning';
    return 'info';
}

function sourceText(source, fallback) {
    if (!source || typeof source !== 'object') return fallback;
    return source.nodeName || source.path || source.sourcePath || source.profile || fallback;
}

function homeAssistantStates() {
    const ha = global.get('homeassistant');
    return ha?.homeAssistant?.states || ha?.states || {};
}

function actualState(entityId) {
    return homeAssistantStates()?.[entityId]?.state;
}

function actualLightSnapshot(target, groupMembers) {
    const targets = expandLightTargets(target, groupMembers).filter(value => value !== '__service__');
    const states = targets.map(entityId => ({ entityId, state: actualState(entityId) || 'unknown' }));
    return {
        targets,
        on: states.filter(entry => entry.state === 'on').map(entry => entry.entityId),
        off: states.filter(entry => entry.state === 'off').map(entry => entry.entityId),
        unknown: states.filter(entry => entry.state !== 'on' && entry.state !== 'off').map(entry => entry.entityId)
    };
}

function actualLightNeedsOutput(action, target, groupMembers) {
    if (target === '__service__') return { needsOutput: false, snapshot: null };
    const isLightAction = action.domain === 'light' || String(action.action || '').startsWith('light.');
    if (!isLightAction) return { needsOutput: false, snapshot: null };

    const snapshot = actualLightSnapshot(target, groupMembers);
    if (action.action === 'light.turn_off') return { needsOutput: snapshot.on.length > 0, snapshot };
    if (action.action === 'light.turn_on') return { needsOutput: snapshot.off.length > 0, snapshot };
    return { needsOutput: false, snapshot };
}

function groupIndexSnapshot(groupMembers) {
    const meta = flow.get(LIGHT_GROUP_INDEX_META_CONTEXT) || {};
    return {
        groups: Object.keys(groupMembers || {}).length,
        updatedAt: meta.updatedAt || null,
        source: meta.source || null,
        haStateEntities: meta.haStateEntities || null
    };
}

function attachStats(diagnostic, acceptedTargets, emittedActions, groupIndex) {
    const decisions = Array.isArray(diagnostic.decisions) ? diagnostic.decisions : [];
    diagnostic.stats = {
        inputActions: diagnostic.request?.actionCount || 0,
        decisions: decisions.length,
        acceptedTargets,
        emittedActions,
        deduplicatedTargets: decisions.filter(decision => decision.status === 'deduplicated').length,
        rejectedTargets: decisions.filter(decision => String(decision.status || '').startsWith('rejected')).length,
        groupIndexGroups: groupIndex?.groups || 0
    };
    return diagnostic;
}

function diagnosisMessages(originalMsg, diagnostic) {
    const decisions = Array.isArray(diagnostic.decisions) && diagnostic.decisions.length > 0 ? diagnostic.decisions : [null];
    const source = sourceText(diagnostic.source, diagnostic.request?.room || 'LI - Koordination');
    return decisions.map(decision => {
        const status = decision?.status || diagnostic.status || 'unknown';
        const target = decision?.target || diagnostic.request?.room || '-';
        const reason = decision?.reason || diagnostic.reason || '-';
        const action = decision?.action || diagnostic.request?.intent || 'request';
        return {
            _msgid: originalMsg._msgid,
            diagnose: {
                level: diagnosticLevel(status),
                domain: 'LI',
                flow: 'LI - Koordination',
                event: 'coordination_' + status,
                source,
                target,
                reason,
                message: status + ': ' + action,
                details: {
                    request: diagnostic.request,
                    decision,
                    decisions: diagnostic.decisions,
                    source: diagnostic.source,
                    status: diagnostic.status,
                    reason: diagnostic.reason,
                    stats: diagnostic.stats,
                    groupIndex: diagnostic.groupIndex,
                    warnings: diagnostic.warnings
                },
                correlation_id: originalMsg._msgid
            }
        };
    });
}

function writeTargetState(state, normalized, target, nextState, priorityClass, priority, now) {
    state[target] = {
        state: nextState,
        hash: hashFor(normalized, target),
        action: normalized.action,
        data: normalized.data,
        origin: normalized.origin,
        intent: normalized.intent,
        priorityClass: nextState === 'off' ? 'none' : priorityClass,
        priority: nextState === 'off' ? 0 : priority,
        room: normalized.room,
        profile: normalized.profile,
        source: normalized.source || {},
        updatedAt: now
    };
}

function recomputeParentGroups(state, changedTargets, groupMembers, parentIndex, directTargets, now) {
    const queue = [...changedTargets];
    const visited = new Set();

    while (queue.length > 0) {
        const changed = queue.shift();
        for (const parent of toArray(parentIndex[changed])) {
            if (visited.has(parent)) continue;
            visited.add(parent);

            const members = toArray(groupMembers[parent]);
            const memberStates = members.map(member => state[member]).filter(Boolean);
            const onMembers = memberStates.filter(entry => entry.state === 'on');
            const offMembers = memberStates.filter(entry => entry.state === 'off');
            let nextState = null;

            if (onMembers.length > 0) nextState = 'on';
            else if (memberStates.length === members.length && offMembers.length === members.length) nextState = 'off';

            if (nextState !== null && !directTargets.has(parent)) {
                const dominant = onMembers.sort((a, b) => Number(b.priority || 0) - Number(a.priority || 0))[0] || {};
                state[parent] = {
                    state: nextState,
                    hash: stableStringify({ action: 'light.aggregate', target: parent, state: nextState }),
                    action: 'light.aggregate',
                    data: {},
                    origin: dominant.origin || 'coordination',
                    intent: 'aggregate_state',
                    priorityClass: nextState === 'off' ? 'none' : (dominant.priorityClass || 'aggregate'),
                    priority: nextState === 'off' ? 0 : Number(dominant.priority || 0),
                    room: dominant.room || '',
                    profile: dominant.profile || '',
                    source: { aggregation: 'light_group_members' },
                    updatedAt: now
                };
            }

            queue.push(parent);
        }
    }
}

