                reason: 'niedrigere Prioritaet ' + priorityClass + '(' + priority + ') gegen ' + previous.priorityClass + '(' + previous.priority + ')',
                action: normalized.action,
                priorityClass
            });
            continue;
        }

        const nextState = lightStateAfter(normalized.action, previous?.state);
        const relatedTargets = relatedTargetsFor(normalized, target, groupMembers);
        directTargets.add(target);
        for (const relatedTarget of relatedTargets) {
