// ====== Konfiguration der Räume ======
// Jeder Raum ist ein Objekt mit allen notwendigen Informationen.
// HINWEIS: Die 'unix'- und 'frequency'-Werte werden von den vorgeschalteten Nodes in das msg-Objekt geladen.
const rooms = [
    { name: "Badezimmer EG",  segmentId: 18, map: "erdgeschoss",  unix: parseFloat(msg.unix.badezimmer_eg)  || 0, frequency: parseFloat(msg.frequency.badezimmer_eg)  || 0 },
    { name: "Esszimmer",      segmentId: 16, map: "erdgeschoss",  unix: parseFloat(msg.unix.esszimmer)      || 0, frequency: parseFloat(msg.frequency.esszimmer)      || 0 },
    { name: "Flur EG",        segmentId: 20, map: "erdgeschoss",  unix: parseFloat(msg.unix.flur_eg)        || 0, frequency: parseFloat(msg.frequency.flur_eg)        || 0 },
    { name: "Küche",          segmentId: 19, map: "erdgeschoss",  unix: parseFloat(msg.unix.kuche)          || 0, frequency: parseFloat(msg.frequency.kuche)          || 0 },
    { name: "Wohnzimmer",     segmentId: 21, map: "erdgeschoss",  unix: parseFloat(msg.unix.wohnzimmer)     || 0, frequency: parseFloat(msg.frequency.wohnzimmer)     || 0 },
    { name: "Ankleidezimmer", segmentId: 19, map: "obergeschoss", unix: parseFloat(msg.unix.ankleidezimmer) || 0, frequency: parseFloat(msg.frequency.ankleidezimmer) || 0 },
    { name: "Badezimmer OG",  segmentId: 20, map: "obergeschoss", unix: parseFloat(msg.unix.badezimmer_og)  || 0, frequency: parseFloat(msg.frequency.badezimmer_og)  || 0 },
    { name: "Familienzimmer", segmentId: 17, map: "obergeschoss", unix: parseFloat(msg.unix.familienzimmer) || 0, frequency: parseFloat(msg.frequency.familienzimmer) || 0 },
    { name: "Flur OG",        segmentId: 16, map: "obergeschoss", unix: parseFloat(msg.unix.flur_og)        || 0, frequency: parseFloat(msg.frequency.flur_og)        || 0 },
    { name: "Schlafzimmer",   segmentId: 18, map: "obergeschoss", unix: parseFloat(msg.unix.schlafzimmer)   || 0, frequency: parseFloat(msg.frequency.schlafzimmer)   || 0 }
];

// Eingehende Werte aus der Nachricht
const map = msg.map;
const check = msg.check || false;
const timestamp = msg.timestamp || Date.now();

// Hilfsfunktion, um zu prüfen, ob ein Raum fällig ist
function isRoomDue(room, now) {
    if (room.frequency <= 0) {
        return false;
    }
    const frequencyInMilliseconds = room.frequency * 24 * 60 * 60 * 1000;
    const timeDifference = now - room.unix;
    return timeDifference >= frequencyInMilliseconds;
}

// Ermitteln, welche Räume insgesamt fällig sind
const dueRooms = rooms.filter(room => isRoomDue(room, timestamp));

// ----- Modus 1: Status prüfen (wenn msg.check === true) -----
if (check === true) {
    if (dueRooms.length > 0) {
        // Die Namen der fälligen Räume sammeln, alphabetisch sortieren und dann zusammenfügen.
        const dueRoomNames = dueRooms.map(room => room.name).sort().join(', ');
        msg.info_text = `Folgende Räume sind zur Reinigung fällig: ${dueRoomNames}.`;
        msg.path = 3; // Nur Info-Text ohne Reinigung
        return msg;
    } else {
        // Nichts ist fällig, also den Flow stoppen.
        return null;
    }
}

// ----- Modus 2: Reinigungs-Warteschlange für ein Stockwerk vorbereiten -----

// Prüfen, ob die übergebene 'map' bekannt ist.
const knownMaps = [...new Set(rooms.map(room => room.map))]; // ["erdgeschoss", "obergeschoss"]
if (!knownMaps.includes(map)) {
    msg.path = 1; // Gleichbleibend für unbekannte Map
    return msg;
}

// Fällige Räume für das angeforderte Stockwerk filtern
const roomsToClean = dueRooms.filter(room => room.map === map);

if (roomsToClean.length > 0) {
    // WICHTIG: Die Reinigungs-Warteschlange in einer Flow-Variablen speichern.
    // Wir speichern das ganze Raum-Objekt, um später alle Daten parat zu haben.
    flow.set("cleaning_queue", roomsToClean);

    const roomsToCleanNames = roomsToClean.map(room => room.name).join(', ');
    msg.info_text = `Automatische Reinigung vorbereitet für: ${roomsToCleanNames}. Starte jetzt den Prozess.`;
    msg.path = 2; // Signalisiert, dass die Reinigungsschleife gestartet werden soll.

    // Diese Nachricht triggert den Start der Schleife
    return msg; 
}

// Holt die aktuelle Warteschlange aus der Flow-Variablen.
let queue = flow.get("cleaning_queue") || [];

// Prüfen, ob noch Räume in der Warteschlange sind.
if (queue.length === 0) {
    node.status({ fill: "green", shape: "dot", text: "Warteschlange leer. Fertig." });
    // Optional hier eine "Alles-Fertig"-Benachrichtigung senden.
    return null; // Stoppt den Flow, wenn die Liste leer ist.
}

// Den nächsten Raum aus der Liste nehmen (First-In, First-Out).
const nextRoom = queue.shift();

// Die verkürzte Liste zurück in die Flow-Variable speichern.
flow.set("cleaning_queue", queue);

// Die Details des aktuellen Raums für die nächsten Schritte in die msg packen.
msg.payload = nextRoom; // Das ganze Raum-Objekt für später aufheben.
msg.segments = [nextRoom.segmentId]; // Wichtig: Nur die eine Segment-ID in einem Array.

node.status({ fill: "blue", shape: "dot", text: `Reinige: ${nextRoom.name}` });
return msg;

// Der Raum, der gerade fertig wurde, steckt in msg.payload.
const cleanedRoom = msg.payload;

// Baut den Namen der input_number Entität dynamisch zusammen.
// Annahme: Die Entitäten heißen z.B. '..._letzte_reinigung_badezimmer_eg_unix_timestamp'.

// Ersetzt Umlaute, macht alles klein und ersetzt Leerzeichen durch Unterstriche.
const entityNamePart = cleanedRoom.name
    .toLowerCase()
    .replace(/ä/g, 'a')
    .replace(/ö/g, 'o')
    .replace(/ü/g, 'u')
    .replace(/ß/g, 'ss')
    .replace(/ /g, '_');

const entityId = `input_number.staubsauger_roborock_s7_maxv_letzte_reinigung_${entityNamePart}_unix_timestamp`;

// Die zusammengebaute Entity-ID und den aktuellen Zeitstempel für den nächsten Node vorbereiten.
msg.timestamp_entity_id = entityId;
msg.timestamp = Date.now(); // Aktueller Zeitpunkt in Millisekunden.

return msg;

const input = msg.ste || msg.payload?.ste || {};

function toArray(value) {
    if (Array.isArray(value)) return value;
    if (value === undefined || value === null || value === '') return [];
    return [value];
}

function actionName(action) {
    return action.action || [action.domain, action.service].filter(Boolean).join('.');
}

function sourceText(source) {
    if (typeof source === 'string') return source;
    if (source && typeof source === 'object') return source.nodeName || source.path || source.sourcePath || source.flow || source.name || 'unbekannt';
    return 'unbekannt';
}

function diagnose(level, event, reason, details) {
    return {
        _msgid: msg._msgid,
        diagnose: {
            level,
            domain: 'STE',
            flow: 'STE - Koordination',
            event,
            source: sourceText(input.source),
            target: details?.target || '-',
            reason,
            message: event + ': ' + reason,
            details,
            correlation_id: input.correlation_id || msg._msgid
        }
    };
}

const diagnostics = [];
const actions = toArray(input.actions);

if (!input || typeof input !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'ungueltiger Request' });
    return [null, diagnose('warning', 'request_invalid', 'msg.ste fehlt oder ist kein Objekt', { payload: msg.payload })];
}

if (actions.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'keine Aktionen' });
    return [null, diagnose('warning', 'request_invalid', 'msg.ste.actions ist leer', { ste: input })];
}

const normalized = [];
for (const raw of actions) {
    if (!raw || typeof raw !== 'object') {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Aktion ist kein Objekt', { action: raw }));
        continue;
    }

    const action = actionName(raw);
    const entityIds = toArray(raw.entityId || raw.entity_id || raw.target?.entity_id).filter((entityId) => typeof entityId === 'string' && entityId.length > 0);
    const [domain, service] = String(action || '').split('.');

    if (domain !== 'switch' || !service) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'nur switch.* Aktionen sind in STE erlaubt', { action: raw }));
        continue;
    }

    const invalidEntity = entityIds.find((entityId) => !entityId.startsWith('switch.'));
    if (invalidEntity) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'nur switch.* Entities sind in STE erlaubt', { action, target: invalidEntity }));
        continue;
    }

    if (entityIds.length === 0) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Entity fehlt', { action }));
        continue;
    }

    normalized.push({
        action,
        entityId: entityIds.length === 1 ? entityIds[0] : entityIds,
        data: raw.data || {},
        priority: Number.isFinite(Number(raw.priority)) ? Number(raw.priority) : 50,
        reason: raw.reason || input.reason || '',
        verify: raw.verify
    });
}

if (normalized.length === 0) {
    node.status({ fill: 'red', shape: 'ring', text: 'alles verworfen' });
    return [null, diagnostics.length ? diagnostics : diagnose('warning', 'request_rejected', 'keine gueltige STE-Aktion', { ste: input })];
}

normalized.sort((a, b) => b.priority - a.priority);

msg.ste = {
    source: input.source || 'unbekannt',
    intent: input.intent || 'socket_action',
    actions: normalized,
    verify: input.verify,
    correlation_id: input.correlation_id || msg._msgid,
    requested_at: input.requested_at || new Date().toISOString(),
    decision: input.decision || {}
};

diagnostics.push(diagnose('info', 'request_accepted', normalized.length + ' Aktion(en) normalisiert', {
    intent: msg.ste.intent,
    actions: normalized.map((action) => ({ action: action.action, entityId: action.entityId, priority: action.priority })),
    correlation_id: msg.ste.correlation_id
}));

node.status({ fill: 'green', shape: 'dot', text: normalized.length + ' Aktion(en)' });
return [msg, diagnostics];

const error = msg.error ?? {};
const source = error.source?.name || error.source?.id || error.source?.type || 'unbekannte Quelle';
const message = error.message || 'Unbekannter Fehler';

msg.diagnose = {
    level: 'error',
    domain: 'STE',
    flow: 'STE - Koordination',
    event: 'flow_error',
    source,
    target: error.source?.id || '',
    reason: message,
    message: 'STE - Koordination Fehler: ' + message + ' (' + source + ')',
    details: { error },
    node_id: error.source?.id ?? null,
    node_type: error.source?.type ?? null,
    correlation_id: msg.ste?.correlation_id || msg.fahrzeug_laden?.correlation_id || msg._msgid
};
msg.payload = msg.diagnose;
return msg;

const req = msg.ste;

function toArray(value) {
    if (Array.isArray(value)) return value;
    if (value === undefined || value === null || value === '') return [];
    return [value];
}

function sourceText(source) {
    if (typeof source === 'string') return source;
    if (source && typeof source === 'object') return source.nodeName || source.path || source.sourcePath || source.flow || source.name || 'unbekannt';
    return 'unbekannt';
}

function diagnose(level, event, target, reason, details) {
    return {
        _msgid: msg._msgid,
        diagnose: {
            level,
            domain: 'STE',
            flow: 'STE - Ausgabe',
            event,
            source: sourceText(req?.source),
            target: target || '-',
            reason,
            message: event + ': ' + reason,
            details,
            correlation_id: req?.correlation_id || msg._msgid
        }
    };
}

const diagnostics = [];
if (!req || !Array.isArray(req.actions)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'kein STE-Request' });
    return [null, diagnose('warning', 'output_invalid_request', '-', 'msg.ste.actions fehlt', { payload: msg.payload })];
}

const messages = [];
for (const action of req.actions) {
    const actionName = action.action || [action.domain, action.service].filter(Boolean).join('.');
    const [domain, service] = String(actionName || '').split('.');
    const entityIds = toArray(action.entityId || action.entity_id || action.target?.entity_id).filter((entityId) => typeof entityId === 'string' && entityId.length > 0);
    const target = entityIds.join(', ');

    if (domain !== 'switch' || !service) {
        diagnostics.push(diagnose('warning', 'output_skipped', target, 'nur switch.* Aktionen sind erlaubt', { action }));
        continue;
    }
    if (entityIds.length === 0 || entityIds.some((entityId) => !entityId.startsWith('switch.'))) {
        diagnostics.push(diagnose('warning', 'output_skipped', target, 'ungueltige oder fehlende switch Entity', { action }));
        continue;
    }

    const out = { ...msg };
    out.topic = 'ste/' + (req.intent || 'socket_action') + '/' + service;
    out.ste_action = action;
    out.ste_verify = action.verify || req.verify || null;
    out.payload = {
        action: actionName,
        target: { entity_id: entityIds },
        data: action.data || {}
    };
    messages.push(out);
