function toNumber(value) {
    const parsed = Number(String(value).replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : null;
}

function compare(current, expected) {
    const currentNumber = toNumber(current);
    const expectedNumber = toNumber(expected);
    if (['lt', 'lte', 'gt', 'gte'].includes(comparator)) {
        if (currentNumber === null || expectedNumber === null) return false;
        if (comparator === 'lt') return currentNumber < expectedNumber;
        if (comparator === 'lte') return currentNumber <= expectedNumber;
        if (comparator === 'gt') return currentNumber > expectedNumber;
        if (comparator === 'gte') return currentNumber >= expectedNumber;
