const ZYKLUS_ARBEIT   = 60 * 60 * 1000;      // 1 Stunde (Bei Arbeitszeit)

// --- KONFIGURATION (Laufzeiten & Schutz) ---
const DAUER_STANDARD = 10 * 60 * 1000; // 10 Min
const DAUER_LEGIO    = 30 * 60 * 1000; // 30 Min (Legionellenschutz)
const MIN_LAUFZEIT   = 5  * 60 * 1000; // 5 Min Mindestlaufzeit

