    const dueA = a.due ? new Date(a.due) : null;
    const dueB = b.due ? new Date(b.due) : null;
    const dateA = getDateWithoutTime(a.due);
    const dateB = getDateWithoutTime(b.due);

    if (dueA && dueB) {
        // Beide haben due-Daten
        if (dateA === dateB) {
            // Gleicher Tag
            const hasTimeA = hasTime(a.due);
            const hasTimeB = hasTime(b.due);
            if (hasTimeA && hasTimeB) {
                // Beide haben Uhrzeit, sortiere nach Uhrzeit
                if (dueA < dueB) return -1;
                if (dueA > dueB) return 1;
                return 0;
            } else if (hasTimeA) {
                // A hat Uhrzeit, B nicht -> A zuerst
                return -1;
            } else if (hasTimeB) {
                // B hat Uhrzeit, A nicht -> B zuerst
                return 1;
            } else {
                // Beide haben keine Uhrzeit, sortiere nach summary
                return getSummaryLower(a).localeCompare(getSummaryLower(b));
            }
        } else {
            // Unterschiedliche Tage, sortiere nach Datum
            if (dueA < dueB) return -1;
            if (dueA > dueB) return 1;
            return 0;
        }
    } else if (dueA) {
        // Nur A hat due-Datum -> A zuerst
        return -1;
    } else if (dueB) {
        // Nur B hat due-Datum -> B zuerst
        return 1;
    } else {
        // Keiner hat due-Datum, sortiere nach summary
        return getSummaryLower(a).localeCompare(getSummaryLower(b));
    }
});

