// Ziel: Eine Liste von To-Do-Einträgen filtern, um alle heute fälligen UND
// alle überfälligen Einträge zu erhalten. Deren Titel werden zu einem
// einzigen, für Sprachausgabe geeigneten Satz zusammengefügt.

// Zugriff auf die Items aus der eingehenden Nachricht
const items = msg.payload["todo.todo_liste"].items;

// --- Hilfsfunktionen ---

// Extrahiert das Datum im Format 'YYYY-MM-DD' aus einem String.
// Funktioniert sowohl für 'YYYY-MM-DD' als auch für 'YYYY-MM-DDTHH:MM:SS'.
const getDateWithoutTime = due => {
    if (due) {
        return due.split('T')[0];
    }
    return null;
};

// Prüft, ob ein Fälligkeitsdatum eine Uhrzeit enthält.
const hasTime = due => due && due.includes('T');

// Gibt den Titel (summary) in Kleinbuchstaben zurück, um die Sortierung zu stabilisieren.
const getSummaryLower = item => (item.summary ? item.summary.toLowerCase() : '');


// --- Hauptlogik ---

// 1. Heutiges Datum im Format YYYY-MM-DD ermitteln
const today = new Date();
const year = today.getFullYear();
// Monate sind 0-basiert, daher +1. padStart sorgt für eine führende Null bei Bedarf (z.B. '09').
const month = String(today.getMonth() + 1).padStart(2, '0');
const day = String(today.getDate()).padStart(2, '0');
const todayString = `${year}-${month}-${day}`;

// 2. Einträge filtern, die heute fällig oder bereits überfällig sind
// *** NEUE LOGIK HIER ***
const dueAndOverdueItems = items.filter(item => {
    const itemDate = getDateWithoutTime(item.due);
    // Behalte den Eintrag, wenn er ein Datum hat, das heute oder früher ist.
    return itemDate && itemDate <= todayString;
});

// 3. Die gefilterten Einträge sortieren (für eine logische Reihenfolge)
//    - Zuerst nach Uhrzeit (falls vorhanden)
//    - Dann alphabetisch nach Titel
dueAndOverdueItems.sort((a, b) => {
    const hasTimeA = hasTime(a.due);
    const hasTimeB = hasTime(b.due);
    const dueA = a.due ? new Date(a.due) : null;
    const dueB = b.due ? new Date(b.due) : null;

    if (hasTimeA && hasTimeB) {
        // Beide haben eine Uhrzeit -> chronologisch sortieren
        // @ts-ignore
        return dueA - dueB;
    } else if (hasTimeA) {
        // Nur A hat eine Uhrzeit -> A kommt zuerst
        return -1;
    } else if (hasTimeB) {
        // Nur B hat eine Uhrzeit -> B kommt zuerst
        return 1;
    } else {
        // Keiner hat eine Uhrzeit -> alphabetisch nach Titel sortieren
        return getSummaryLower(a).localeCompare(getSummaryLower(b));
    }
});


// 4. Nur die Titel (summaries) der gefilterten und sortierten Einträge extrahieren
const summaries = dueAndOverdueItems.map(item => item.summary);

// 5. Den finalen Satz für die Sprachausgabe erstellen
let outputSpeech;
const itemCount = summaries.length;

if (itemCount === 0) {
    outputSpeech = "Es stehen keine fälligen Termine an.";
} else if (itemCount === 1) {
    outputSpeech = `Folgender Termin ist fällig: ${summaries[0]}.`;
} else {
    // Für eine natürliche Sprachausgabe: "A, B und C" statt "A, B, C"
    const lastItem = summaries.pop();
    const firstItems = summaries.join(', ');
    outputSpeech = `Folgende Termine sind fällig: ${firstItems} und ${lastItem}.`;
}

// 6. Die ursprüngliche Nachricht mit dem neuen Satz als Payload ersetzen und senden
msg.info_text = outputSpeech;
return msg;

