function getTodayForecast(forecastArray) {
    if (!forecastArray || !Array.isArray(forecastArray)) return [];
    const today = new Date().toISOString().slice(0, 10);
    return forecastArray.filter(item => item.datetime && item.datetime.startsWith(today));
}

function findMaxValue(todayArray) {
    if (!todayArray || todayArray.length === 0) return null;
    return Math.max(...todayArray.map(item => item.value));
}

function findMinValue(todayArray) {
    if (!todayArray || todayArray.length === 0) return null;
    return Math.min(...todayArray.map(item => item.value));
}

function findAverageValue(todayArray) {
    if (!todayArray || todayArray.length === 0) return null;
    const sum = todayArray.reduce((acc, item) => acc + item.value, 0);
    return sum / todayArray.length;
}

function calculateWindChill(temperature, windSpeed) {
    if (temperature > 10 || windSpeed < 5) return temperature;
    return 13.12 + 0.6215 * temperature - 11.37 * Math.pow(windSpeed, 0.16) + 0.3965 * temperature * Math.pow(windSpeed, 0.16);
}

function calculateHeatIndex(temperature, humidity) {
    if (temperature < 27) return temperature;
    const T = temperature;
    const RH = humidity;
    return -8.78469475556 + 1.61139411 * T + 2.33854883889 * RH - 0.14611605 * T * RH - 0.012308094 * T * T - 0.0164248277778 * RH * RH + 0.002211732 * T * T * RH + 0.00072546 * T * RH * RH - 0.000003582 * T * T * RH * RH;
}

function mapWeatherCondition(condition) {
    const translations = {
        "sunny": "strahlendem Sonnenschein", "clear-night": "klarem Himmel", "cloudy": "einem bewölkten Himmel",
        "exceptional": "außergewöhnlichen Bedingungen", "fog": "dichtem Nebel", "hail": "Hagel",
        "lightning": "einem Gewitter", "lightning-rainy": "Gewitter mit Regen", "partlycloudy": "leichter Bewölkung",
        "pouring": "starkem Regen", "rainy": "Regen", "snowy": "Schneefall",
        "snowy-rainy": "Schneeregen", "windy": "starkem Wind", "windy-variant": "starkem Wind"
    };
    return translations[condition] || condition;
}

function getWindDirection(degree) {
    if (typeof degree !== 'number') return "unbekannter Richtung";
    const directions = ["Norden", "Nordosten", "Osten", "Südosten", "Süden", "Südwesten", "Westen", "Nordwesten"];
    return directions[Math.round(degree / 45) % 8];
}

function mapPollenLevel(level) {
    const numericLevel = parseFloat(level);
    if (numericLevel === 0) return "keine"; if (numericLevel === 0.5) return "keine bis geringe";
    if (numericLevel === 1) return "geringe"; if (numericLevel === 1.5) return "geringe bis mittlere";
    if (numericLevel === 2) return "mittlere"; if (numericLevel === 2.5) return "mittlere bis hohe";
    if (numericLevel === 3) return "hohe"; return "unbekannte";
}

function getPollenReport(pollenData) {
    let warnings = [];
    for (const [pollenName, data] of Object.entries(pollenData)) {
        if (!data) continue;
        const level = data.state;
        const numericLevel = parseFloat(level);
        // LOGIK-UPDATE: Warnung bereits bei 0.5 ausgeben
        if (numericLevel >= 0.5) {
            warnings.push(`einer ${mapPollenLevel(numericLevel)} Belastung durch ${pollenName}`);
        }
    }
    if (warnings.length === 0) return "Gute Nachrichten für Allergiker: Heute ist keine nennenswerte Pollenbelastung zu erwarten.";
    return `Zum Schluss noch ein Hinweis für Allergiker: Es wird ${warnings.join(' sowie ')} erwartet.`;
}

function generatePeriodReport(period, hourlyData, todayTemp) {
    const periodHours = [];
    if (period.start > period.end) {
        for (let i = period.start; i <= 23; i++) periodHours.push(i);
        for (let i = 0; i <= period.end; i++) periodHours.push(i);
    } else {
        for (let i = period.start; i <= period.end; i++) periodHours.push(i);
    }

    const filterByPeriod = (dataArray) => {
        if (!dataArray) return [];
        return dataArray.filter(item => periodHours.includes(new Date(item.datetime).getHours()));
    };

    const periodTemp = filterByPeriod(hourlyData.temperatur);
    if (periodTemp.length === 0) return null;

    const periodCloud = filterByPeriod(hourlyData.bewoelkung);
    const periodPrecipChance = filterByPeriod(hourlyData.niederschlag_wahrs);
    const periodWindGust = filterByPeriod(hourlyData.wind_boen);

    const minT = findMinValue(periodTemp);
    const maxT = findMaxValue(periodTemp);
    const avgCloud = findAverageValue(periodCloud);
    const maxPrecip = findMaxValue(periodPrecipChance);
    const maxGust = findMaxValue(periodWindGust);

    let reportParts = [];

    // Bewölkung und Sonne
    if (avgCloud !== null) {
        if (avgCloud < 25) {
            if (period.name === "In der Nacht") {
                reportParts.push("wird es klar");
            } else {
                reportParts.push("bleibt es sonnig");
            }
        } else if (avgCloud < 50) reportParts.push("wird es wechselnd bewölkt");
        else if (avgCloud < 75) reportParts.push("ist es stark bewölkt");
        else reportParts.push("ist es bedeckt");
    }

    // Temperatur
    if (minT !== null && maxT !== null) {
        if (Math.round(minT) === Math.round(maxT)) {
            reportParts.push(`bei Temperaturen um ${Math.round(maxT)} Grad`);
        } else {
            reportParts.push(`bei Temperaturen zwischen ${Math.round(minT)} und ${Math.round(maxT)} Grad`);
        }
    }

    // Niederschlag
    if (maxPrecip !== null && maxPrecip > 30) {
        const avgTempForPrecip = findAverageValue(periodTemp);
        let precipType = "Regen";
        if (avgTempForPrecip < 1) precipType = "Schnee";
        else if (avgTempForPrecip < 3) precipType = "Schneeregen";
        reportParts.push(`und es besteht die Gefahr von ${precipType}schauern`);
    }

    // Wind
    if (maxGust !== null && maxGust > 40) {
        reportParts.push(`begleitet von vereinzelten Windböen`);
    }

    if (reportParts.length === 0) return null;

    return `${period.name} ${reportParts.join(' ')}.`;
}


