const input = resolveInput();

const ALLOWED = {
    input_boolean: ['turn_on', 'turn_off', 'toggle'],
    input_select: ['select_option', 'select_first', 'select_last', 'select_next', 'select_previous'],
    input_number: ['set_value', 'increment', 'decrement'],
    input_text: ['set_value'],
    input_datetime: ['set_datetime'],
    button: ['press'],
    counter: ['increment', 'decrement', 'reset', 'configure'],
    timer: ['start', 'cancel', 'finish', 'pause'],
    todo: ['add_item', 'update_item', 'remove_item', 'clear_completed']
};

const REQUIRED_DATA = {
    'input_select.select_option': ['option'],
    'input_number.set_value': ['value'],
    'input_text.set_value': ['value']
};

const PRIORITY = {
    critical: 100,
    safety: 90,
    system: 80,
    schedule: 60,
    routine: 50,
    maintenance: 40,
    technical: 30,
    default: 50
};

function resolveInput() {
    const candidates = [msg.sy, msg.sy_request, msg.payload?.sy, msg.payload];
    return candidates.find((candidate) =>
        candidate && typeof candidate === 'object' && !Array.isArray(candidate) &&
        (Array.isArray(candidate.actions) || candidate.action || candidate.domain || candidate.service)
    ) || {};
}

function toArray(value) {
    if (Array.isArray(value)) return value;
    if (value === undefined || value === null || value === '') return [];
    return [value];
}

function uniqueStrings(values) {
    return [...new Set(values.filter((value) => typeof value === 'string' && value.length > 0))];
}

function stableStringify(value) {
    if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
    if (value && typeof value === 'object') {
        return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
    }
    return JSON.stringify(value);
}

function actionName(raw) {
    return raw.action || [raw.domain, raw.service].filter(Boolean).join('.');
}

function sourceText(source) {
    if (typeof source === 'string') return source;
    if (source && typeof source === 'object') return source.nodeName || source.path || source.sourcePath || source.flow || source.name || 'unbekannt';
    return 'unbekannt';
}

function priorityFor(raw) {
    if (Number.isFinite(Number(raw.priority))) return Number(raw.priority);
    const priorityClass = raw.priorityClass || input.priorityClass || raw.origin || input.origin || 'default';
    return PRIORITY[priorityClass] ?? PRIORITY.default;
}

function diagnose(level, event, reason, details = {}) {
    return {
        _msgid: msg._msgid,
        diagnose: {
            level,
            domain: 'SY',
            flow: 'SY - Koordination',
            event,
            source: sourceText(input.source),
            target: details.target || '-',
            reason,
            message: event + ': ' + reason,
            details,
            correlation_id: input.correlation_id || msg._msgid
        }
    };
}

function missingRequiredData(domain, service, data) {
    const required = REQUIRED_DATA[domain + '.' + service] || [];
    return required.filter((key) => !Object.prototype.hasOwnProperty.call(data || {}, key));
}

function entityPrefix(domain) {
    return domain + '.';
}

const rawActions = Array.isArray(input.actions) ? input.actions : (input.action || input.domain || input.service ? [input] : []);
const diagnostics = [];

if (!input || typeof input !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'ungueltiger Request' });
    return [null, diagnose('warning', 'request_invalid', 'msg.sy fehlt oder ist kein Objekt', { payload: msg.payload })];
}

if (rawActions.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'keine Aktionen' });
    return [null, diagnose('warning', 'request_invalid', 'msg.sy.actions ist leer', { sy: input })];
}

const normalized = [];
const seen = new Set();

for (const raw of rawActions) {
    if (!raw || typeof raw !== 'object') {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Aktion ist kein Objekt', { action: raw }));
        continue;
    }

    const action = actionName(raw);
    const [domain, service] = String(action || '').split('.');
    const entityIds = uniqueStrings(toArray(raw.entityId || raw.entity_id || raw.target?.entity_id));
    const data = raw.data || {};
    const target = entityIds.join(', ');

    if (!domain || !service || !ALLOWED[domain]?.includes(service)) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Aktion ist in SY nicht erlaubt', { action: raw, target }));
        continue;
    }

    const invalidEntity = entityIds.find((entityId) => !entityId.startsWith(entityPrefix(domain)));
    if (invalidEntity) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Entity passt nicht zur Domain ' + domain, { action, target: invalidEntity }));
        continue;
    }

    if (entityIds.length === 0) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Entity fehlt', { action }));
        continue;
    }

    const missing = missingRequiredData(domain, service, data);
    if (missing.length > 0) {
        diagnostics.push(diagnose('warning', 'action_skipped', 'Pflichtdaten fehlen: ' + missing.join(', '), { action, target, data }));
        continue;
    }

    const normalizedAction = {
        action,
        domain,
        service,
        entityId: entityIds,
        data,
        priority: priorityFor(raw),
        priorityClass: raw.priorityClass || input.priorityClass || raw.origin || input.origin || 'default',
        origin: raw.origin || input.origin || 'system',
        intent: raw.intent || input.intent || 'system_action',
        reason: raw.reason || input.reason || '',
        source: raw.source || input.source || {}
    };

    const key = stableStringify({
        action: normalizedAction.action,
        entityId: normalizedAction.entityId,
        data: normalizedAction.data
    });

    if (seen.has(key)) {
        diagnostics.push(diagnose('debug', 'action_deduplicated', 'identische Aktion im Request dedupliziert', { action: normalizedAction, target }));
        continue;
    }

    seen.add(key);
    normalized.push(normalizedAction);
}

if (normalized.length === 0) {
    node.status({ fill: 'red', shape: 'ring', text: 'alles verworfen' });
    return [null, diagnostics.length ? diagnostics : diagnose('warning', 'request_rejected', 'keine gueltige SY-Aktion', { sy: input })];
}

normalized.sort((a, b) => b.priority - a.priority);

msg.sy = {
    schema: 'sy.request.v1',
    source: input.source || 'unbekannt',
    origin: input.origin || 'system',
    intent: input.intent || 'system_action',
    actions: normalized,
    correlation_id: input.correlation_id || msg._msgid,
    requested_at: input.requested_at || new Date().toISOString(),
    decision: {
        status: 'accepted',
        acceptedActions: normalized.length,
        skippedActions: rawActions.length - normalized.length
    }
};

msg.payload = msg.sy;
diagnostics.push(diagnose('info', 'request_accepted', normalized.length + ' Aktion(en) normalisiert', {
    intent: msg.sy.intent,
    actions: normalized.map((action) => ({
        action: action.action,
        entityId: action.entityId,
        priority: action.priority,
        priorityClass: action.priorityClass
    })),
    correlation_id: msg.sy.correlation_id
}));

node.status({ fill: 'green', shape: 'dot', text: normalized.length + ' Aktion(en)' });
return [msg, diagnostics];

const error = msg.error ?? {};
const source = error.source?.name || error.source?.id || error.source?.type || 'unbekannte Quelle';
const message = error.message || 'Unbekannter Fehler';

msg.diagnose = {
