    flow: 'SY - Koordination',
    event: 'flow_error',
    source,
    target: error.source?.id || '',
    reason: message,
    message: 'SY - Koordination Fehler: ' + message + ' (' + source + ')',
    details: { error },
    node_id: error.source?.id ?? null,
    node_type: error.source?.type ?? null,
    correlation_id: msg.sy?.correlation_id || msg._msgid
};
msg.payload = msg.diagnose;
return msg;

